"""Offline illustrations included with the cafeteria prototype."""
import base64
from pathlib import Path

SAMPLE_IMAGES = {
    'adobo.png': '',
    'iced_tea.png': '',
    'pancit.png': '',
    'sandwich.png': '',
    'siomai.png': '',
    'turon.png': '',
    'water.png': '',
}


def ensure_sample_images(base: Path) -> None:
    target = base / "images"
    target.mkdir(parents=True, exist_ok=True)
    for filename, encoded in SAMPLE_IMAGES.items():
        file = target / filename
        if not file.exists():
            file.write_bytes(base64.b64decode(encoded))